'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const C=window.K9_CONFIG||{};
const DEFAULT_SETTINGS={id:1,organization_name:C.ORGANIZATION_NAME||'K9 Napoletano Academy',app_name:C.APP_NAME||'K9 Studio Dogsitter',subtitle:'',description:'',address:'',postal_code:'',city:'',province:'',country:'Italia',phone:'',mobile:'',email:'',website:'',vat_number:'',fiscal_code:'',iban:'',social_text:'',footer_text:'',legal_text:'',primary_color:'#0f5f53',secondary_color:'#153e75',header_color:'#ffffff',card_color:'#ffffff',button_color:'#0f5f53',logo_url:'',logo_size:48,logo_position:'sinistra',show_logo_pdf:true,show_header_pdf:true,show_footer_pdf:true,show_fiscal_data_pdf:true,show_qr_pdf:false,show_photos_pdf:false,show_signatures_pdf:false};
const state={session:null,profile:null,customers:[],dogs:[],profiles:[],services:[],documents:[],trash:[],settings:{...DEFAULT_SETTINGS}};
const roleLabels={owner:'Datore di lavoro',vice_admin:'Vice amministratore',dipendente:'Dipendente'};
const statusLabels={programmato:'Programmato',in_corso:'In corso',da_verificare:'Da verificare',chiuso:'Chiuso',annullato:'Annullato'};
const esc=v=>String(v??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));
const money=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(Number(n||0));
const dateIT=v=>v?new Date(v+'T12:00:00').toLocaleDateString('it-IT'):'—';
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const toast=m=>{const e=$('#toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)};
const isAdmin=()=>['owner','vice_admin'].includes(state.profile?.role), isOwner=()=>state.profile?.role==='owner', isEmployee=()=>state.profile?.role==='dipendente';
function configured(){return /^https:\/\/.+\.supabase\.co$/.test(C.SUPABASE_URL||'')&&!String(C.SUPABASE_ANON_KEY||'').startsWith('INCOLLA_')}
function authHeaders(extra={}){return {'apikey':C.SUPABASE_ANON_KEY,'Authorization':`Bearer ${state.session?.access_token||C.SUPABASE_ANON_KEY}`,'Content-Type':'application/json',...extra}}
async function refreshSession(){if(!state.session?.refresh_token)throw Error('Sessione scaduta.');const r=await fetch(`${C.SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:C.SUPABASE_ANON_KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:state.session.refresh_token})});const d=await r.json();if(!r.ok)throw Error(d.error_description||d.msg||'Sessione scaduta.');state.session=d;localStorage.setItem('k9_session',JSON.stringify(d));return d}
async function request(path,opt={},retry=true){if(!configured())throw Error('Configura config.js prima della pubblicazione.');let r=await fetch(C.SUPABASE_URL+path,{...opt,headers:{...authHeaders(),...(opt.headers||{})}});if(r.status===401&&retry&&state.session?.refresh_token){await refreshSession();return request(path,opt,false)}const text=await r.text();let data=null;try{data=text?JSON.parse(text):null}catch{data=text}if(!r.ok)throw Error(data?.message||data?.error_description||data?.hint||text||`Errore ${r.status}`);return data}
const select=(table,q='select=*')=>request(`/rest/v1/${table}?${q}`);
const insert=(table,data)=>request(`/rest/v1/${table}`,{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(data)});
const update=(table,id,data)=>request(`/rest/v1/${table}?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(data)});
const rpc=(name,body={})=>request(`/rest/v1/rpc/${name}`,{method:'POST',body:JSON.stringify(body)});
async function login(email,password){const r=await fetch(`${C.SUPABASE_URL}/auth/v1/token?grant_type=password`,{method:'POST',headers:{apikey:C.SUPABASE_ANON_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const d=await r.json();if(!r.ok)throw Error(d.error_description||d.msg||'Accesso non riuscito');state.session=d;localStorage.setItem('k9_session',JSON.stringify(d));await bootstrap()}
async function logout(){try{await request('/auth/v1/logout',{method:'POST'})}catch{}localStorage.removeItem('k9_session');location.reload()}
async function restore(){try{state.session=JSON.parse(localStorage.getItem('k9_session')||'null')}catch{}if(!state.session)return false;try{if(Date.now()/1000>(state.session.expires_at||0)-60)await refreshSession();await bootstrap();return true}catch(e){localStorage.removeItem('k9_session');return false}}
async function bootstrap(){const p=await select('profiles',`select=*&id=eq.${state.session.user.id}&limit=1`);state.profile=p[0];if(!state.profile||!state.profile.active)throw Error('Account non attivo.');await loadSettings();applyIdentity();$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');$('#roleLabel').textContent=`${state.profile.full_name||state.profile.email} · ${roleLabels[state.profile.role]||state.profile.role}`;buildNav();await loadAll();show('dashboard')}
function buildNav(){const a=[['dashboard','Dashboard'],['customers','Clienti'],['dogs','Cani'],['employees','Utenti'],['services','Servizi'],['payments','Economia'],['documents','Documenti'],['audit','Log'],['trash','Cestino'],['profile','Pass'],['settings','Impostazioni']];const e=[['dashboard','Oggi'],['customers','Clienti assegnati'],['dogs','Cani assegnati'],['services','I miei servizi'],['compensation','Compensi'],['profile','Il mio pass']];$('#nav').innerHTML=(isAdmin()?a:e).map(([id,l])=>`<button data-screen="${id}">${l}</button>`).join('')}
async function loadDocuments(){try{return await select('dogsitter_document_versions','select=*&order=created_at.desc')}catch(e){console.warn('Archivio versionato non ancora installato:',e.message);try{return await select('dogsitter_documents','select=*&order=created_at.desc')}catch{return []}}}
async function loadAll(){if(isAdmin()){[state.customers,state.dogs,state.profiles,state.services,state.documents]=await Promise.all([select('customers','select=*&deleted_at=is.null&order=last_name.asc,first_name.asc'),select('dogs','select=*&deleted_at=is.null&order=name.asc'),select('profiles','select=*&order=full_name.asc'),select('dogsitter_services','select=*&deleted_at=is.null&order=service_date.desc,service_time.asc'),loadDocuments()])}else{const d=await rpc('employee_workspace');state.customers=d.customers||[];state.dogs=d.dogs||[];state.services=d.services||[];state.documents=[];state.profiles=[]}}
function show(id){$$('.screen').forEach(e=>e.classList.add('hidden'));$('#'+id).classList.remove('hidden');$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.screen===id));render(id)}
function render(id){({dashboard:renderDashboard,customers:renderCustomers,dogs:renderDogs,employees:renderEmployees,services:renderServices,compensation:renderComp,payments:renderPayments,documents:renderDocs,audit:renderAudit,trash:renderTrash,profile:renderPass,settings:renderSettings}[id]||(()=>{}))()}
const cname=id=>{const c=state.customers.find(x=>x.id===id);return c?`${c.first_name} ${c.last_name}`:'—'}, dname=id=>state.dogs.find(x=>x.id===id)?.name||'—', pname=id=>state.profiles.find(x=>x.id===id)?.full_name||'—';
const matured=s=>['da_verificare','chiuso'].includes(s.status);
async function loadSettings(){try{const rows=await select('app_settings','select=*&id=eq.1&limit=1');state.settings={...DEFAULT_SETTINGS,...(rows[0]||{})}}catch(e){state.settings={...DEFAULT_SETTINGS};console.warn('Impostazioni non ancora installate:',e.message)}}
function identityLogo(){return state.settings.logo_url||'assets/logo.png'}
function applyIdentity(){const x=state.settings||DEFAULT_SETTINGS;document.documentElement.style.setProperty('--p',x.primary_color||DEFAULT_SETTINGS.primary_color);document.documentElement.style.setProperty('--p2',x.secondary_color||DEFAULT_SETTINGS.secondary_color);document.documentElement.style.setProperty('--header',x.header_color||'#ffffff');document.documentElement.style.setProperty('--card',x.card_color||'#ffffff');document.documentElement.style.setProperty('--button',x.button_color||x.primary_color||DEFAULT_SETTINGS.button_color);document.title=x.app_name||DEFAULT_SETTINGS.app_name;const logo=identityLogo();const appLogo=$('#appLogo');if(appLogo){appLogo.src=logo;appLogo.style.width=`${Number(x.logo_size||48)}px`;appLogo.style.height=`${Number(x.logo_size||48)}px`}const loginLogo=$('.auth-card .logo');if(loginLogo)loginLogo.src=logo;const brand=$('#appBrandName');if(brand)brand.textContent=x.app_name||DEFAULT_SETTINGS.app_name;const b=$('.brand');if(b){b.style.flexDirection=x.logo_position==='centro'?'column':'row';b.style.textAlign=x.logo_position==='centro'?'center':'left';b.style.marginLeft=x.logo_position==='destra'?'auto':''}}
function settingField(name,label,type='text',wide=false){const v=state.settings[name]??'';return `<label class="${wide?'wide':''}">${label}<input name="${name}" type="${type}" value="${esc(v)}"></label>`}
function settingArea(name,label){return `<label class="wide">${label}<textarea name="${name}">${esc(state.settings[name]||'')}</textarea></label>`}
function checkField(name,label){return `<label class="check-row"><input name="${name}" type="checkbox" ${state.settings[name]?'checked':''}><span>${label}</span></label>`}
function renderSettings(){if(!isAdmin()){show('dashboard');return}const s=state.settings;$('#settingsPanel').innerHTML=`<form id="identityForm"><section class="settings-block"><h3>Logo</h3><div class="logo-preview"><img id="settingsLogoPreview" src="${esc(identityLogo())}" alt="Logo attivo"><div><label>Carica nuovo logo<input id="identityLogoFile" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"></label><p class="muted">Il logo attuale resta quello predefinito finché non ne carichi uno nuovo.</p><button type="button" id="restoreDefaultLogo">Ripristina logo predefinito</button></div></div><div class="settings-grid">${settingField('logo_size','Dimensione logo (28-160 px)','number')}<label>Posizione logo<select name="logo_position"><option value="sinistra" ${s.logo_position==='sinistra'?'selected':''}>Sinistra</option><option value="centro" ${s.logo_position==='centro'?'selected':''}>Centro</option><option value="destra" ${s.logo_position==='destra'?'selected':''}>Destra</option></select></label></div></section><section class="settings-block"><h3>Intestazione</h3><div class="settings-grid">${settingField('organization_name','Nome attività')}${settingField('app_name','Nome applicazione')}${settingField('subtitle','Sottotitolo', 'text', true)}${settingArea('description','Descrizione')}${settingField('address','Indirizzo')}${settingField('postal_code','CAP')}${settingField('city','Comune')}${settingField('province','Provincia')}${settingField('country','Nazione')}${settingField('phone','Telefono')}${settingField('mobile','Cellulare')}${settingField('email','Email','email')}${settingField('website','Sito web')}${settingField('vat_number','Partita IVA')}${settingField('fiscal_code','Codice fiscale')}${settingField('iban','IBAN', 'text', true)}${settingArea('social_text','Social e altri riferimenti')}</div></section><section class="settings-block"><h3>Grafica</h3><div class="settings-grid">${settingField('primary_color','Colore principale','color')}${settingField('secondary_color','Colore secondario','color')}${settingField('header_color','Colore intestazione','color')}${settingField('card_color','Colore schede','color')}${settingField('button_color','Colore pulsanti','color')}</div></section><section class="settings-block"><h3>PDF e piè di pagina</h3><div class="settings-grid">${settingArea('footer_text','Testo piè di pagina')}${settingArea('legal_text','Note legali / privacy')}${checkField('show_logo_pdf','Mostra logo nel PDF')}${checkField('show_header_pdf','Mostra intestazione nel PDF')}${checkField('show_footer_pdf','Mostra piè di pagina nel PDF')}${checkField('show_fiscal_data_pdf','Mostra dati fiscali nel PDF')}${checkField('show_qr_pdf','Mostra QR identificativo nel PDF')}${checkField('show_photos_pdf','Mostra fotografie nel PDF')}${checkField('show_signatures_pdf','Mostra firme nel PDF')}</div></section><div class="settings-actions"><button class="primary" type="submit">Salva impostazioni</button><button type="button" id="resetIdentity">Ripristina tutti i valori iniziali</button></div></form>`;$('#identityForm').onsubmit=saveSettings;$('#identityLogoFile').onchange=previewAndUploadLogo;$('#restoreDefaultLogo').onclick=()=>setLogoUrl('');$('#resetIdentity').onclick=resetSettings}
async function saveSettings(e){e.preventDefault();const f=new FormData(e.currentTarget),data={};for(const [k,v] of f.entries())data[k]=v;['show_logo_pdf','show_header_pdf','show_footer_pdf','show_fiscal_data_pdf','show_qr_pdf','show_photos_pdf','show_signatures_pdf'].forEach(k=>data[k]=f.has(k));data.logo_size=Math.max(28,Math.min(160,Number(data.logo_size||48)));await request('/rest/v1/app_settings?id=eq.1',{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(data)});state.settings={...state.settings,...data};applyIdentity();toast('Impostazioni salvate')}
async function previewAndUploadLogo(e){const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){toast('Il logo supera 5 MB');e.target.value='';return}const ext=(file.name.split('.').pop()||'png').toLowerCase();const path=`identity/logo-${Date.now()}.${ext}`;const r=await fetch(`${C.SUPABASE_URL}/storage/v1/object/app-assets/${path}`,{method:'POST',headers:{apikey:C.SUPABASE_ANON_KEY,Authorization:`Bearer ${state.session.access_token}`,'Content-Type':file.type||'application/octet-stream','x-upsert':'true'},body:file});const t=await r.text();if(!r.ok)throw Error(t||'Caricamento logo non riuscito');const url=`${C.SUPABASE_URL}/storage/v1/object/public/app-assets/${path}`;await setLogoUrl(url)}
async function setLogoUrl(url){await request('/rest/v1/app_settings?id=eq.1',{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({logo_url:url})});state.settings.logo_url=url;applyIdentity();const p=$('#settingsLogoPreview');if(p)p.src=identityLogo();toast(url?'Logo aggiornato':'Logo predefinito ripristinato')}
async function resetSettings(){if(!confirm('Ripristinare intestazione, colori e logo ai valori iniziali?'))return;const data={...DEFAULT_SETTINGS};delete data.id;await request('/rest/v1/app_settings?id=eq.1',{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(data)});state.settings={...DEFAULT_SETTINGS};applyIdentity();renderSettings();toast('Impostazioni ripristinate')}

function renderDashboard(){
  const today=localDate(), todays=state.services.filter(s=>s.service_date===today), upcoming=state.services.filter(s=>s.service_date>=today&&s.status!=='annullato').sort((a,b)=>String(a.service_date+a.service_time).localeCompare(String(b.service_date+b.service_time))).slice(0,4);
  if(isAdmin()){
    const toVerify=state.services.filter(s=>s.status==='da_verificare').length;
    const toCollect=state.services.filter(s=>s.customer_payment_status==='da_incassare'&&matured(s)).reduce((a,s)=>a+Number(s.customer_amount||0),0);
    const toPay=state.services.filter(s=>s.employee_payment_status==='da_liquidare'&&matured(s)).reduce((a,s)=>a+Number(s.employee_compensation||0),0);
    $('#dashboard').innerHTML=`<div class="page-title"><div><span class="eyebrow">PANORAMICA OPERATIVA</span><h2>Dashboard amministrativa</h2><p class="muted">Situazione aggiornata dell’attività.</p></div><span class="today-chip">${new Date().toLocaleDateString('it-IT',{weekday:'long',day:'2-digit',month:'long'})}</span></div><div class="stats dashboard-stats"><div class="stat stat-customers"><span>Clienti attivi</span><strong>${state.customers.filter(c=>c.status==='attivo').length}</strong><small>Anagrafiche disponibili</small></div><div class="stat stat-dogs"><span>Cani</span><strong>${state.dogs.filter(d=>d.active).length}</strong><small>Profili attivi</small></div><div class="stat stat-today"><span>Servizi oggi</span><strong>${todays.length}</strong><small>${todays.reduce((a,s)=>a+Number(s.daily_visits||1),0)} uscite previste</small></div><div class="stat stat-review"><span>Da verificare</span><strong>${toVerify}</strong><small>Rapporti in attesa</small></div><div class="stat stat-income"><span>Da incassare</span><strong>${money(toCollect)}</strong><small>Importi cliente maturati</small></div><div class="stat stat-pay"><span>Da liquidare</span><strong>${money(toPay)}</strong><small>Compensi dipendenti</small></div></div><div class="section-title-row"><div><h3>Servizi di oggi</h3><p class="muted">Attività programmate per la giornata.</p></div></div><div class="grid service-grid">${todays.map(serviceCard).join('')||'<div class="card empty-state"><strong>Nessun servizio oggi</strong><span>La giornata non contiene attività programmate.</span></div>'}</div>${!todays.length&&upcoming.length?`<div class="section-title-row compact"><div><h3>Prossimi servizi</h3></div></div><div class="grid service-grid">${upcoming.map(serviceCard).join('')}</div>`:''}`
  }else{
    $('#dashboard').innerHTML=`<div class="page-title"><div><span class="eyebrow">AREA DIPENDENTE</span><h2>Il mio lavoro di oggi</h2></div></div><div class="stats dashboard-stats"><div class="stat stat-today"><span>Servizi</span><strong>${todays.length}</strong><small>Assegnati oggi</small></div><div class="stat stat-dogs"><span>Uscite</span><strong>${todays.reduce((a,s)=>a+Number(s.daily_visits||1),0)}</strong><small>Totale previsto</small></div><div class="stat stat-pay"><span>Compenso maturato</span><strong>${money(todays.filter(matured).reduce((a,s)=>a+Number(s.employee_compensation),0))}</strong><small>Solo servizi maturati</small></div></div><div class="grid service-grid">${todays.map(serviceCard).join('')||'<div class="card empty-state"><strong>Nessun servizio oggi</strong><span>Non risultano attività assegnate.</span></div>'}</div>`
  }
}
function renderCustomers(){
  $('[data-action="new-customer"]')?.classList.toggle('hidden',!isAdmin());
  $('#customerList').innerHTML=state.customers.map(c=>{const dogs=state.dogs.filter(d=>d.customer_id===c.id);const services=state.services.filter(x=>x.customer_id===c.id&&x.status!=='annullato').sort((a,b)=>String(a.service_date).localeCompare(String(b.service_date)));const next=services.find(x=>x.service_date>=localDate());return `<article class="card entity-card customer-card"><div class="entity-card-head"><div class="entity-avatar">${esc((c.first_name||'?').slice(0,1)+(c.last_name||'').slice(0,1))}</div><div><span class="entity-kicker">CLIENTE</span><h3>${esc(c.first_name)} ${esc(c.last_name)}</h3></div></div><div class="entity-details"><p><span>Telefono</span><strong>${esc(c.phone||'Non indicato')}</strong></p><p><span>Comune</span><strong>${esc(c.city||'Non indicato')}</strong></p><p><span>Cani associati</span><strong>${dogs.length}${dogs.length?` · ${esc(dogs.map(d=>d.name).join(', '))}`:''}</strong></p><p><span>Dipendente assegnato</span><strong>${esc(pname(c.assigned_employee_id))}</strong></p>${next?`<p class="wide"><span>Prossimo servizio</span><strong>${dateIT(next.service_date)} ${esc(String(next.service_time||'').slice(0,5))} · ${esc(next.service_type||'Servizio')}</strong></p>`:''}</div>${isAdmin()?`<div class="card-actions"><button class="primary-soft" onclick="openCustomer('${c.id}')">Apri / modifica</button><button class="danger" onclick="archiveEntity('customers','${c.id}','cliente ${esc(c.first_name+' '+c.last_name)}')">Elimina</button></div>`:`<div class="operational-note"><b>Note operative</b><span>${esc(c.operational_notes||'Nessuna nota operativa')}</span></div>`}</article>`}).join('')||'<div class="card empty-state"><strong>Nessun cliente</strong><span>Aggiungi il primo cliente per iniziare.</span></div>'
}
function renderDogs(){
  $('[data-action="new-dog"]')?.classList.toggle('hidden',!isAdmin());
  $('#dogList').innerHTML=state.dogs.map(d=>`<article class="card entity-card dog-card"><div class="entity-card-head"><div class="entity-avatar dog-avatar">🐕</div><div><span class="entity-kicker">CANE</span><h3>${esc(d.name)}</h3><p class="entity-subtitle">${esc(d.breed||'Razza non indicata')}</p></div></div><div class="entity-details"><p><span>Proprietario</span><strong>${esc(cname(d.customer_id))}</strong></p><p><span>Microchip</span><strong>${esc(d.microchip||'Non indicato')}</strong></p><p class="wide"><span>Alimentazione</span><strong>${esc(d.feeding_notes||'Nessuna indicazione')}</strong></p><p class="wide"><span>Farmaci / allergie</span><strong>${esc(d.medical_notes||'Nessuna indicazione')}</strong></p><p class="wide"><span>Comportamento e routine</span><strong>${esc(d.behavior_notes||d.routine_notes||'Nessuna nota')}</strong></p></div>${isAdmin()?`<div class="card-actions"><button class="primary-soft" onclick="openDog('${d.id}')">Apri / modifica</button><button class="danger" onclick="archiveEntity('dogs','${d.id}','cane ${esc(d.name)}')">Elimina</button></div>`:''}</article>`).join('')||'<div class="card empty-state"><strong>Nessun cane</strong><span>Collega un cane a un cliente per visualizzarlo qui.</span></div>'
}
function renderEmployees(){
  const groups=[
    {key:'administrators',label:'Amministratori',rows:state.profiles.filter(p=>p.role==='owner'||p.role==='vice_admin')},
    {key:'employees',label:'Dipendenti',rows:state.profiles.filter(p=>p.role==='dipendente')}
  ];
  $('#employeeList').innerHTML=groups.map(group=>`<details class="account-group" open><summary><span>${group.label}</span><strong>${group.rows.length}</strong></summary><div class="account-group-body">${group.rows.map(p=>{const assigned=state.services.filter(s=>s.employee_id===p.id&&s.status!=='annullato').length;return `<details class="account-row" data-profile-id="${p.id}"><summary><div class="account-summary-main"><span class="entity-avatar employee-avatar">${esc((p.full_name||p.email||'?').slice(0,2).toUpperCase())}</span><div><strong>${esc(p.full_name||p.email)}</strong><small>${esc(roleLabels[p.role]||p.role)} · ${p.active?'Attivo':'Sospeso'}</small></div></div><span class="account-chevron">⌄</span></summary><div class="account-expanded"><div class="entity-details"><p><span>Codice</span><strong>${esc(p.employee_code||'Non assegnato')}</strong></p><p><span>Qualifica</span><strong>${esc(p.qualification||'Non indicata')}</strong></p><p><span>Servizi associati</span><strong>${assigned}</strong></p><p><span>Stato</span><strong class="${p.active?'text-success':'text-danger'}">${p.active?'Attivo':'Sospeso'}</strong></p></div>${p.is_owner?'<div class="protected-note">Titolare protetto</div>':''}<div class="card-actions"><button class="primary-soft" onclick="openEmployee('${p.id}')">Seleziona e gestisci</button>${!p.is_owner&&p.active?`<button class="danger" onclick="deactivateUser('${p.id}','${esc(p.full_name||p.email)}')">Disattiva</button>`:''}</div></div></details>`}).join('')||'<div class="empty-compact">Nessun account in questa categoria.</div>'}</div></details>`).join('')
}
function serviceCard(s){
  const margin=Number(s.customer_amount||0)-Number(s.employee_compensation||0), status=statusLabels[s.status]||s.status, time=String(s.service_time||'').slice(0,5), visits=Number(s.daily_visits||1);let actions='';
  if(isEmployee()){if(s.status==='programmato')actions=`<button class="primary" onclick="startService('${s.id}')">Inizia servizio</button>`;if(s.status==='in_corso')actions=`<button class="primary" onclick="completeService('${s.id}')">Compila e termina</button>`}
  else{actions=`<button class="primary-soft" onclick="openService('${s.id}')">Apri / modifica</button><button class="danger" onclick="archiveEntity('dogsitter_services','${s.id}','servizio')">Elimina</button>${s.status==='da_verificare'?`<button class="primary" onclick="approveService('${s.id}')">Approva e genera PDF</button>`:''}${s.status==='chiuso'?`<button onclick="createDocumentVersionFromService('${s.id}','customer')">PDF cliente</button><button onclick="createDocumentVersionFromService('${s.id}','employee')">PDF dipendente</button><button onclick="markSent('${s.id}')">Segna inviato</button>`:''}`}
  const economics=isEmployee()?`<div class="employee-compensation"><span>Compenso della scheda</span><strong>${money(s.employee_compensation)}</strong><small>${visits} ${visits===1?'uscita':'uscite'}</small></div>`:`<div class="economic-split"><div><span>Importo cliente</span><strong>${money(s.customer_amount)}</strong></div><div><span>Compenso dipendente</span><strong>${money(s.employee_compensation)}</strong></div><div><span>Margine attività</span><strong>${money(margin)}</strong></div></div>`;
  return `<article class="card service-card"><div class="service-card-top"><div><span class="entity-kicker">${esc(s.service_type||'SERVIZIO')}</span><h3>${esc(dname(s.dog_id))}</h3><p>${esc(cname(s.customer_id))}</p></div><span class="status-badge status-${esc(s.status)}">${esc(status)}</span></div><div class="service-facts"><div><span>Data</span><strong>${dateIT(s.service_date)}</strong></div><div><span>Ora</span><strong>${esc(time||'—')}</strong></div><div><span>Uscite</span><strong>${visits}</strong></div><div><span>Dipendente</span><strong>${esc(pname(s.employee_id))}</strong></div></div>${economics}${s.started_at?`<div class="timeline-note"><b>Orari effettivi</b><span>Inizio ${new Date(s.started_at).toLocaleString('it-IT')}${s.completed_at?` · Fine ${new Date(s.completed_at).toLocaleString('it-IT')}`:''}</span></div>`:''}${s.report_text?`<div class="operational-note"><b>Rapporto</b><span>${esc(s.report_text)}</span></div>`:''}<div class="service-actions">${actions}</div></article>`
}
function renderServices(){$('[data-action="new-service"]')?.classList.toggle('hidden',!isAdmin());const d=$('#serviceDateFilter').value,st=$('#serviceStatusFilter').value;$('#serviceList').innerHTML=state.services.filter(s=>(!d||s.service_date===d)&&(!st||s.status===st)).map(serviceCard).join('')||'<div class="card">Nessun servizio.</div>'}
function periodTotals(filter){const rows=state.services.filter(s=>filter(s)&&matured(s));return {sum:rows.reduce((a,s)=>a+Number(s.employee_compensation),0),visits:rows.reduce((a,s)=>a+Number(s.daily_visits||1),0)}}
function renderComp(){const now=new Date(),today=localDate(now),week=new Date(now);week.setDate(now.getDate()-((now.getDay()+6)%7));const ws=localDate(week),month=today.slice(0,7);const defs=[['Oggi',s=>s.service_date===today],['Settimana',s=>s.service_date>=ws&&s.service_date<=today],['Mese',s=>s.service_date.startsWith(month)]];$('#compCards').innerHTML=defs.map(([l,f])=>{const t=periodTotals(f);return `<div class="stat"><span>${l}</span><strong>${money(t.sum)}</strong><small>${t.visits} uscite</small></div>`}).join('')+`<div class="stat"><span>Da liquidare</span><strong>${money(state.services.filter(s=>matured(s)&&s.employee_payment_status==='da_liquidare').reduce((a,s)=>a+Number(s.employee_compensation),0))}</strong></div>`;$('#compList').innerHTML=state.services.filter(matured).map(serviceCard).join('')}
function renderPayments(){const maturedRows=state.services.filter(matured),income=maturedRows.filter(s=>s.customer_payment_status==='incassato').reduce((a,s)=>a+Number(s.customer_amount),0),toIncome=maturedRows.filter(s=>s.customer_payment_status==='da_incassare').reduce((a,s)=>a+Number(s.customer_amount),0),toPay=maturedRows.filter(s=>s.employee_payment_status==='da_liquidare').reduce((a,s)=>a+Number(s.employee_compensation),0),margin=maturedRows.reduce((a,s)=>a+Number(s.customer_amount)-Number(s.employee_compensation),0);$('#paymentSummary').innerHTML=`<div class="stat"><span>Incassato</span><strong>${money(income)}</strong></div><div class="stat"><span>Da incassare</span><strong>${money(toIncome)}</strong></div><div class="stat"><span>Da liquidare</span><strong>${money(toPay)}</strong></div><div class="stat"><span>Quota attività maturata</span><strong>${money(margin)}</strong></div>`;$('#paymentList').innerHTML=maturedRows.map(s=>`<article class="card"><h3>${esc(cname(s.customer_id))} · ${esc(dname(s.dog_id))}</h3><p>${dateIT(s.service_date)} · Cliente ${money(s.customer_amount)} (${esc(s.customer_payment_status)})</p><p>Dipendente ${money(s.employee_compensation)} (${esc(s.employee_payment_status)})</p><div class="service-actions"><button onclick="setCustomerPaid('${s.id}')">Segna cliente incassato</button><button onclick="setEmployeePaid('${s.id}')">Segna dipendente liquidato</button></div></article>`).join('')||'<div class="card">Nessun movimento maturato.</div>'}
function documentTypeLabel(d){return (d.document_type||'customer')==='employee'?'PDF dipendente':'PDF cliente'}
function documentStatusLabel(v){return ({generating:'In generazione',generated:'Generato',inviato:'Inviato',archived:'Archiviato'}[v]||v||'Generato')}
function renderDocs(){const host=$('#documentList'),docs=state.documents||[],active=docs.filter(d=>d.status!=='archived').length,customers=docs.filter(d=>(d.document_type||'customer')==='customer').length,employees=docs.filter(d=>d.document_type==='employee').length,sent=docs.filter(d=>d.status==='inviato').length;host.innerHTML=`<div class="document-summary"><div class="stat"><span>Documenti</span><strong>${docs.length}</strong></div><div class="stat"><span>Attivi</span><strong>${active}</strong></div><div class="stat"><span>PDF cliente</span><strong>${customers}</strong></div><div class="stat"><span>PDF dipendente</span><strong>${employees}</strong></div><div class="stat"><span>Inviati</span><strong>${sent}</strong></div></div><div class="document-toolbar"><input id="documentSearch" type="search" placeholder="Cerca cliente, cane, dipendente o file"><select id="documentTypeFilter"><option value="">Tutti i documenti</option><option value="customer">PDF cliente</option><option value="employee">PDF dipendente</option></select><select id="documentStatusFilter"><option value="">Tutti gli stati</option><option value="generated">Generati</option><option value="inviato">Inviati</option><option value="archived">Archiviati</option></select></div><div id="documentCards" class="document-grid"></div>`;const draw=()=>{const q=$('#documentSearch').value.trim().toLowerCase(),type=$('#documentTypeFilter').value,status=$('#documentStatusFilter').value,rows=docs.filter(d=>(!type||(d.document_type||'customer')===type)&&(!status||d.status===status)&&(!q||[d.file_name,d.customer_name,d.dog_name,d.employee_name,d.title].some(v=>String(v||'').toLowerCase().includes(q))));$('#documentCards').innerHTML=rows.map(d=>`<article class="card document-card ${d.is_active===false?'is-superseded':''}"><div class="document-card-head"><div><span class="document-kind ${d.document_type==='employee'?'internal':''}">${documentTypeLabel(d)}</span><h3>${esc(d.file_name||d.title||'Documento')}</h3></div><span class="document-version">V${Number(d.version||1)}</span></div><div class="document-meta"><div><span>Cliente</span><strong>${esc(d.customer_name||cname(d.customer_id))}</strong></div><div><span>Cane</span><strong>${esc(d.dog_name||dname(d.dog_id))}</strong></div><div><span>Dipendente</span><strong>${esc(d.employee_name||pname(d.employee_id))}</strong></div><div><span>Data servizio</span><strong>${dateIT(d.service_date)}</strong></div></div><div class="document-state"><span class="pill">${esc(documentStatusLabel(d.status))}</span>${d.is_active===false?'<span class="pill muted-pill">Versione superata</span>':'<span class="pill active-pill">Versione attiva</span>'}</div><p class="muted">Creato ${d.created_at?new Date(d.created_at).toLocaleString('it-IT'):'—'}</p><div class="service-actions"><button onclick="openDocument('${d.id}')">Apri</button><button onclick="downloadStoredDocument('${d.id}')">Scarica</button><button onclick="shareStoredDocument('${d.id}')">Condividi</button>${d.service_id&&d.status!=='archived'?`<button onclick="regenerateDocument('${d.id}')">Nuova versione</button>`:''}${d.status!=='inviato'&&(d.document_type||'customer')==='customer'?`<button onclick="markDocumentSent('${d.id}')">Segna inviato</button>`:''}${d.status!=='archived'?`<button class="danger" onclick="archiveDocument('${d.id}')">Archivia</button>`:''}</div></article>`).join('')||'<div class="card">Nessun documento corrispondente.</div>'};$('#documentSearch').oninput=draw;$('#documentTypeFilter').onchange=draw;$('#documentStatusFilter').onchange=draw;draw()}
function auditSubject(a){const d=a.details?.new||a.details?.old||{};if(a.table_name==='customers')return [d.first_name,d.last_name].filter(Boolean).join(' ');if(a.table_name==='dogs')return d.name||'';if(a.table_name==='dogsitter_services')return d.service_type||'';if(a.table_name==='profiles')return d.full_name||d.email||'';return ''}function auditDetails(a){const d=a.details?.new||a.details?.old||{};const hidden=new Set(['id','created_by','updated_at','created_at','customer_id','employee_id','dog_id','deleted_by']);return Object.entries(d).filter(([k,v])=>!hidden.has(k)&&v!==null&&v!=='').slice(0,12).map(([k,v])=>`<div><b>${esc(k.replaceAll('_',' '))}:</b> ${esc(typeof v==='object'?JSON.stringify(v):v)}</div>`).join('')||'<div>Nessun dettaglio aggiuntivo.</div>'}async function renderAudit(){const clearBtn=$('#clearAuditLog');clearBtn?.classList.toggle('hidden',!isOwner());if(clearBtn)clearBtn.onclick=clearAuditLog;const rows=await select('audit_log','select=*&order=created_at.desc&limit=250');const tableNames={customers:'Cliente',dogs:'Cane',dogsitter_services:'Servizio',profiles:'Utente'};const actionNames={INSERT:'Creato',UPDATE:'Modificato',DELETE:'Eliminato'};$('#auditList').innerHTML=rows.map((a,i)=>{const who=state.profiles.find(p=>p.id===a.user_id)?.full_name||'Sistema';const obj=tableNames[a.table_name]||a.table_name||'Elemento';const subject=auditSubject(a);const title=`${actionNames[a.action]||a.action} ${obj.toLowerCase()}${subject?`: ${subject}`:''}`;return `<article class="card"><div class="audit-title"><b>${esc(title)}</b><span class="pill">${esc(who)}</span></div><p class="muted">${new Date(a.created_at).toLocaleString('it-IT')}</p><button class="link-button" type="button" onclick="toggleAuditDetails('audit-${i}',this)">Mostra dettagli</button><div id="audit-${i}" class="audit-friendly hidden">${auditDetails(a)}</div></article>`}).join('')||'<div class="card">Nessuna attività registrata.</div>'}
async function clearAuditLog(){if(!isOwner())return;const first=confirm('Vuoi azzerare definitivamente tutto il Registro attività? Questa operazione non può essere annullata.');if(!first)return;const typed=prompt('Per confermare scrivi AZZERA');if(typed!=='AZZERA'){toast('Operazione annullata');return}const btn=$('#clearAuditLog');try{if(btn){btn.disabled=true;btn.textContent='Azzeramento...'}const result=await rpc('clear_audit_log');const remaining=await select('audit_log','select=id&limit=1');if(remaining.length)throw Error('Il database non ha cancellato tutte le registrazioni. Riesegui la migrazione 4.1.1 in Supabase.');await renderAudit();const deleted=typeof result==='number'?result:(result?.deleted_count??null);toast(deleted===null?'Registro attività azzerato definitivamente':`Registro azzerato: ${deleted} voci eliminate`)}catch(e){console.error('Errore azzeramento registro:',e);toast(e.message||'Impossibile azzerare il Registro attività')}finally{if(btn){btn.disabled=false;btn.textContent='Azzera definitivamente'}}}
function passCode(p){if(p.employee_code)return p.employee_code;const suffix=String(p.id||'').replace(/-/g,'').slice(-6).toUpperCase();return p.is_owner||p.role==='owner'?`K9-TIT-${suffix||'000001'}`:`K9-${suffix||'000001'}`}
function passValidity(p){if(p.is_owner||p.role==='owner')return 'Illimitata';return p.pass_expires_at?dateIT(p.pass_expires_at):'Da definire'}
function passIssued(p){return p.pass_issued_at?dateIT(p.pass_issued_at):(p.created_at?new Date(p.created_at).toLocaleDateString('it-IT'):'—')}
function qrImageUrl(value){return `https://api.qrserver.com/v1/create-qr-code/?size=220x220&margin=8&data=${encodeURIComponent(value)}`}
function renderPass(){const p=state.profile;const code=passCode(p);const verifyPayload=`K9PASS|${code}|${p.active?'ATTIVO':'SOSPESO'}`;$('#passCard').innerHTML=`<div class="pass-shell"><article id="printablePass" class="pass pass-professional"><div class="pass-topline"><span>PASS IDENTIFICATIVO</span><span class="pass-status ${p.active?'is-active':'is-suspended'}">${p.active?'ATTIVO':'SOSPESO'}</span></div><div class="pass-head"><div class="pass-photo"><img src="${esc(p.photo_url||identityLogo())}" alt="Foto o logo"></div><div class="pass-person"><small>${esc(state.settings.organization_name||DEFAULT_SETTINGS.organization_name)}</small><h2>${esc(p.full_name||p.email)}</h2><p>${esc(p.qualification||roleLabels[p.role]||p.role)}</p></div></div><div class="pass-data"><div><span>Codice</span><strong>${esc(code)}</strong></div><div><span>Emissione</span><strong>${esc(passIssued(p))}</strong></div><div><span>Validità</span><strong>${esc(passValidity(p))}</strong></div><div><span>Ruolo</span><strong>${esc(roleLabels[p.role]||p.role)}</strong></div></div><div class="pass-verification"><img src="${qrImageUrl(verifyPayload)}" alt="QR di verifica del pass" crossorigin="anonymous"><div><span>Codice di verifica</span><strong>${esc(code)}</strong><small>Scansiona per verificare codice e stato del pass.</small></div></div></article><div class="pass-actions"><button type="button" class="primary" onclick="downloadPassPdf()">Scarica PDF</button><button type="button" onclick="sharePassPdf()">Condividi PDF</button><button type="button" onclick="sharePass()">Condividi dati pass</button>${isAdmin()?'<button type="button" onclick="openCurrentProfile()">Modifica dati pass</button>':''}</div><p class="muted pass-note">Per modificare foto, codice, qualifica o scadenza usa “Modifica dati pass”.</p></div>`}
window.sharePass=async()=>{const p=state.profile,code=passCode(p);const text=`${state.settings.organization_name||DEFAULT_SETTINGS.organization_name}\n${p.full_name||p.email}\n${roleLabels[p.role]||p.role}\nCodice: ${code}\nStato: ${p.active?'ATTIVO':'SOSPESO'}\nValidità: ${passValidity(p)}`;try{if(navigator.share)await navigator.share({title:'Pass K9',text});else{await navigator.clipboard.writeText(text);toast('Dati del pass copiati')}}catch(e){if(e.name!=='AbortError')toast('Condivisione non disponibile')}};
window.openCurrentProfile=()=>openEmployee(state.profile.id);
function modal(title,html,onSave){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').showModal();$('#modalForm').onsubmit=async e=>{e.preventDefault();if(e.submitter?.value==='cancel')return $('#modal').close();try{await onSave(new FormData(e.currentTarget));$('#modal').close();await loadAll();render($$('.screen:not(.hidden)')[0]?.id||'dashboard');toast('Salvato')}catch(err){toast(err.message)}}}
const field=(n,l,v='',type='text',extra='')=>`<label>${l}<input name="${n}" type="${type}" value="${esc(v)}" ${extra}></label>`;
window.openCustomer=id=>{const c=state.customers.find(x=>x.id===id)||{};const em=state.profiles.filter(p=>p.role==='dipendente'&&p.active);modal(id?'Modifica cliente':'Nuovo cliente',`<div class="form-grid">${field('first_name','Nome',c.first_name,'text','required')}${field('last_name','Cognome',c.last_name,'text','required')}${field('phone','Telefono',c.phone)}${field('email','Email',c.email,'email')}${field('address','Indirizzo',c.address)}${field('city','Comune',c.city)}${field('emergency_contact','Contatto emergenza',c.emergency_contact)}<label>Dipendente assegnato<select name="assigned_employee_id"><option value="">Non assegnato</option>${em.map(p=>`<option value="${p.id}" ${p.id===c.assigned_employee_id?'selected':''}>${esc(p.full_name)}</option>`).join('')}</select></label><label class="wide">Note operative<textarea name="operational_notes">${esc(c.operational_notes||'')}</textarea></label></div>`,async f=>{const d=Object.fromEntries(f);d.assigned_employee_id=d.assigned_employee_id||null;id?await update('customers',id,d):await insert('customers',d)})};
window.openDog=id=>{const d=state.dogs.find(x=>x.id===id)||{};modal(id?'Modifica cane':'Nuovo cane',`<div class="form-grid">${field('name','Nome',d.name,'text','required')}<label>Proprietario<select name="customer_id" required>${state.customers.map(c=>`<option value="${c.id}" ${c.id===d.customer_id?'selected':''}>${esc(c.first_name+' '+c.last_name)}</option>`).join('')}</select></label>${field('breed','Razza',d.breed)}${field('microchip','Microchip',d.microchip)}<label class="wide">Alimentazione<textarea name="feeding_notes">${esc(d.feeding_notes||'')}</textarea></label><label class="wide">Farmaci/allergie<textarea name="medical_notes">${esc(d.medical_notes||'')}</textarea></label><label class="wide">Comportamento e routine<textarea name="behavior_notes">${esc(d.behavior_notes||'')}</textarea></label></div>`,async f=>{const x=Object.fromEntries(f);id?await update('dogs',id,x):await insert('dogs',x)})};
window.openService=id=>{
  const service=state.services.find(item=>item.id===id)||{};
  const employees=state.profiles.filter(profile=>profile.role==='dipendente'&&profile.active);
  const defaultTypes=['Passeggiata','Compagnia e cura a domicilio','Pasto, acqua e attenzioni','Pensione','Visita domiciliare','Somministrazione farmaci'];
  const currentType=service.service_type||'Passeggiata';
  const isCustomType=currentType&&!defaultTypes.includes(currentType);
  const durations=[15,30,45,60,90,120,180,240];
  const visits=[1,2,3,4,5,6];
  const statuses=[
    ['programmato','Programmato'],
    ['in_corso','In corso'],
    ['da_verificare','Da verificare'],
    ['chiuso','Chiuso'],
    ['annullato','Annullato']
  ];
  const selectedCustomer=service.customer_id||state.customers[0]?.id||'';
  const assignedEmployee=service.employee_id||state.customers.find(customer=>customer.id===selectedCustomer)?.assigned_employee_id||'';
  modal(id?'Modifica servizio':'Nuovo servizio',`<div class="form-grid">
    <label>Cliente<select id="serviceCustomer" name="customer_id" required><option value="">Seleziona cliente</option>${state.customers.map(customer=>`<option value="${customer.id}" ${customer.id===selectedCustomer?'selected':''}>${esc(customer.first_name+' '+customer.last_name)}</option>`).join('')}</select></label>
    <label>Cane<select id="serviceDog" name="dog_id" required><option value="">Seleziona cane</option></select></label>
    <label>Dipendente<select id="serviceEmployee" name="employee_id" required><option value="">Seleziona dipendente</option>${employees.map(profile=>`<option value="${profile.id}" ${profile.id===assignedEmployee?'selected':''}>${esc(profile.full_name)}</option>`).join('')}</select></label>
    <label>Tipo servizio<select id="serviceType" name="service_type_choice" required>${defaultTypes.map(value=>`<option value="${esc(value)}" ${value===currentType?'selected':''}>${esc(value)}</option>`).join('')}<option value="__custom__" ${isCustomType?'selected':''}>Altro / personalizzato</option></select></label>
    <label id="customServiceTypeWrap" class="wide ${isCustomType?'':'hidden'}">Tipo servizio personalizzato<input id="customServiceType" name="service_type_custom" value="${esc(isCustomType?currentType:'')}" maxlength="80" placeholder="Scrivi il tipo di servizio"></label>
    ${field('service_date','Data',service.service_date||localDate(),'date','required')}
    ${field('service_time','Ora',String(service.service_time||'09:00').slice(0,5),'time','required')}
    <label>Durata prevista<select name="planned_duration_minutes" required>${durations.map(value=>`<option value="${value}" ${Number(service.planned_duration_minutes||30)===value?'selected':''}>${value<60?value+' minuti':(value/60)+' ore'}</option>`).join('')}</select></label>
    <label>Numero uscite<select name="daily_visits" required>${visits.map(value=>`<option value="${value}" ${Number(service.daily_visits||1)===value?'selected':''}>${value}</option>`).join('')}</select></label>
    <label>Stato servizio<select name="status" required>${statuses.map(([value,label])=>`<option value="${value}" ${value===(service.status||'programmato')?'selected':''}>${label}</option>`).join('')}</select></label>
    ${field('customer_amount','Importo cliente',service.customer_amount||0,'number','min="0" step="0.01" required')}
    ${field('employee_compensation','Compenso dipendente',service.employee_compensation||0,'number','min="0" step="0.01" required')}
    <label class="wide">Note operative<textarea name="operational_notes" maxlength="2000">${esc(service.operational_notes||'')}</textarea></label>
  </div>`,async formData=>{
    const payload=Object.fromEntries(formData);
    payload.service_type=payload.service_type_choice==='__custom__'?String(payload.service_type_custom||'').trim():payload.service_type_choice;
    delete payload.service_type_choice;
    delete payload.service_type_custom;
    ['planned_duration_minutes','daily_visits','customer_amount','employee_compensation'].forEach(key=>payload[key]=Number(payload[key]));
    if(!payload.customer_id||!payload.dog_id||!payload.employee_id)throw Error('Seleziona cliente, cane e dipendente.');
    if(!payload.service_type)throw Error('Indica il tipo di servizio.');
    const selectedDog=state.dogs.find(dog=>dog.id===payload.dog_id);
    if(!selectedDog||selectedDog.customer_id!==payload.customer_id)throw Error('Il cane selezionato non appartiene al cliente indicato.');
    if(payload.employee_compensation>payload.customer_amount)throw Error('Il compenso dipendente non può superare l’importo cliente.');
    id?await update('dogsitter_services',id,payload):await insert('dogsitter_services',payload);
  });
  const customerSelect=$('#serviceCustomer');
  const dogSelect=$('#serviceDog');
  const employeeSelect=$('#serviceEmployee');
  const typeSelect=$('#serviceType');
  const customWrap=$('#customServiceTypeWrap');
  const customInput=$('#customServiceType');
  const fillDogs=()=>{
    const dogs=state.dogs.filter(dog=>dog.customer_id===customerSelect.value);
    dogSelect.innerHTML='<option value="">Seleziona cane</option>'+dogs.map(dog=>`<option value="${dog.id}" ${dog.id===service.dog_id?'selected':''}>${esc(dog.name)}</option>`).join('');
    if(!id&&dogs.length===1)dogSelect.value=dogs[0].id;
    const assigned=state.customers.find(customer=>customer.id===customerSelect.value)?.assigned_employee_id;
    if(!id&&assigned&&employees.some(profile=>profile.id===assigned))employeeSelect.value=assigned;
  };
  const toggleCustomType=()=>{
    const custom=typeSelect.value==='__custom__';
    customWrap.classList.toggle('hidden',!custom);
    customInput.required=custom;
    if(custom)customInput.focus();
  };
  customerSelect.onchange=fillDogs;
  typeSelect.onchange=toggleCustomType;
  fillDogs();
  toggleCustomType();
};
