$('#logoutBtn').onclick=logout;$('#nav').onclick=e=>{const b=e.target.closest('[data-screen]');if(b)show(b.dataset.screen)};
$('[data-action="new-customer"]').onclick=()=>openCustomer();$('[data-action="new-dog"]').onclick=()=>openDog();$('[data-action="new-service"]').onclick=()=>openService();$('[data-action="new-employee"]').onclick=createAccount;
$('#serviceDateFilter').onchange=renderServices;$('#serviceStatusFilter').onchange=renderServices;$('#clearFilters').onclick=()=>{$('#serviceDateFilter').value='';$('#serviceStatusFilter').value='';renderServices()};
if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js'));
restore();
